Fix by removing the unconditional fp->conn assignment and rejecting the
replay when fp->conn is non-NULL. This is consistent with
ksmbd_lookup_durable_fd(), which also rejects file handles with a
non-NULL fp->conn. For disconnected file handles (fp->conn == NULL),
ksmbd_reopen_durable_fd() handles setting fp->conn.

Fixes: c8efcc786146 ("ksmbd: add support for durable handles v1/v2")
Signed-off-by: Hyunwoo Kim <imv4bel@gmail.com>
Acked-by: Namjae Jeon <linkinjeon@kernel.org>
Signed-off-by: Steve French <stfrench@microsoft.com>

Here is the root cause:
In parse_durable_handle_context(), when handling a DURABLE_REQ_V2 context with SMB2_FLAGS_REPLAY_OPERATION, the code unconditionally assigns dh_info->fp->conn = conn, even if fp->conn already points to an active connection. This overwrites the connection pointer, causing the original connection to become stale. Later, when the original connection is freed, __ksmbd_close_fd() dereferences the stale fp->conn (via spin_lock), resulting in a use-after-free.

Here is the patch:

 static int parse_durable_handle_context(struct ksmbd_work *work,
 					struct smb2_create_req *req,
 					struct lease_ctx_info *lc,
 					struct durable_info *dh_info)
 {
 	struct ksmbd_conn *conn = work->conn;
 	struct create_context *context;
 	int dh_idx, err = 0;
 	u64 persistent_id = 0;
 	int req_op_level;
 	static const char * const durable_arr[] = {"DH2C", "DHnC", "DH2Q", "DHnQ"};

 	req_op_level = req->RequestedOplockLevel;
 	for (dh_idx = DURABLE_RECONN_V2; dh_idx <= ARRAY_SIZE(durable_arr);
 	     dh_idx++) {
 		context = smb2_find_context_vals(req, durable_arr[dh_idx - 1], 4);
 		if (IS_ERR(context)) {
 			err = PTR_ERR(context);
 			goto out;
 		}
 		if (!context)
 			continue;

 		switch (dh_idx) {
 		case DURABLE_RECONN_V2:
 		{
 			struct create_durable_handle_reconnect_v2 *recon_v2;

 			if (dh_info->type == DURABLE_RECONN ||
 			    dh_info->type == DURABLE_REQ_V2) {
 				err = -EINVAL;
 				goto out;
 			}

 			if (le16_to_cpu(context->DataOffset) +
 				le32_to_cpu(context->DataLength) <
 			    sizeof(struct create_durable_handle_reconnect_v2)) {
 				err = -EINVAL;
 				goto out;
 			}

 			recon_v2 = (struct create_durable_handle_reconnect_v2 *)context;
 			persistent_id = recon_v2->dcontext.Fid.PersistentFileId;
 			dh_info->fp = ksmbd_lookup_durable_fd(persistent_id);
 			if (!dh_info->fp) {
 				ksmbd_debug(SMB, "Failed to get durable handle state\n");
 				err = -EBADF;
 				goto out;
 			}

 			if (memcmp(dh_info->fp->create_guid, recon_v2->dcontext.CreateGuid,
 				   SMB2_CREATE_GUID_SIZE)) {
 				err = -EBADF;
 				ksmbd_put_durable_fd(dh_info->fp);
 				goto out;
 			}

 			dh_info->type = dh_idx;
 			dh_info->reconnected = true;
 			ksmbd_debug(SMB,
 				"reconnect v2 Persistent-id from reconnect = %llu\n",
 					persistent_id);
 			break;
 		}
 		case DURABLE_RECONN:
 		{
 			create_durable_reconn_t *recon;

 			if (dh_info->type == DURABLE_RECONN_V2 ||
 			    dh_info->type == DURABLE_REQ_V2) {
 				err = -EINVAL;
 				goto out;
 			}

 			if (le16_to_cpu(context->DataOffset) +
 				le32_to_cpu(context->DataLength) <
 			    sizeof(create_durable_reconn_t)) {
 				err = -EINVAL;
 				goto out;
 			}

 			recon = (create_durable_reconn_t *)context;
 			persistent_id = recon->Data.Fid.PersistentFileId;
 			dh_info->fp = ksmbd_lookup_durable_fd(persistent_id);
 			if (!dh_info->fp) {
 				ksmbd_debug(SMB, "Failed to get durable handle state\n");
 				err = -EBADF;
 				goto out;
 			}

 			dh_info->type = dh_idx;
 			dh_info->reconnected = true;
 			ksmbd_debug(SMB, "reconnect Persistent-id from reconnect = %llu\n",
 				    persistent_id);
 			break;
 		}
 		case DURABLE_REQ_V2:
 		{
 			struct create_durable_req_v2 *durable_v2_blob;

 			if (dh_info->type == DURABLE_RECONN ||
 			    dh_info->type == DURABLE_RECONN_V2) {
 				err = -EINVAL;
 				goto out;
 			}

 			if (le16_to_cpu(context->DataOffset) +
 				le32_to_cpu(context->DataLength) <
 			    sizeof(struct create_durable_req_v2)) {
 				err = -EINVAL;
 				goto out;
 			}

 			durable_v2_blob =
 				(struct create_durable_req_v2 *)context;
 			ksmbd_debug(SMB, "Request for durable v2 open\n");
 			dh_info->fp = ksmbd_lookup_fd_cguid(durable_v2_blob->dcontext.CreateGuid);
 			if (dh_info->fp) {
 				if (!memcmp(conn->ClientGUID, dh_info->fp->client_guid,
 					    SMB2_CLIENT_GUID_SIZE)) {
 					if (!(req->hdr.Flags & SMB2_FLAGS_REPLAY_OPERATION)) {
 						err = -ENOEXEC;
 						ksmbd_put_durable_fd(dh_info->fp);
 						goto out;
 					}

-					dh_info->fp->conn = conn;
+					if (dh_info->fp->conn) {
+						ksmbd_put_durable_fd(dh_info->fp);
+						err = -EBADF;
+						goto out;
+					}
 					dh_info->reconnected = true;
 					goto out;
 				}
 			}

 			if ((lc && (lc->req_state & SMB2_LEASE_HANDLE_CACHING_LE)) ||
 			    req_op_level == SMB2_OPLOCK_LEVEL_BATCH) {
 				dh_info->CreateGuid =
 					durable_v2_blob->dcontext.CreateGuid;
 				dh_info->persistent =
 					le32_to_cpu(durable_v2_blob->dcontext.Flags);
 				dh_info->timeout =
 					le32_to_cpu(durable_v2_blob->dcontext.Timeout);
 				dh_info->type = dh_idx;
 			}
 			break;
 		}
 		case DURABLE_REQ:
 			if (dh_info->type == DURABLE_RECONN)
 				goto out;
 			if (dh_info->type == DURABLE_RECONN_V2 ||
 			    dh_info->type == DURABLE_REQ_V2) {
 				err = -EINVAL;
 				goto out;
 			}

 			if ((lc && (lc->req_state & SMB2_LEASE_HANDLE_CACHING_LE)) ||
 			    req_op_level == SMB2_OPLOCK_LEVEL_BATCH) {
 				ksmbd_debug(SMB, "Request for durable open\n");
 				dh_info->type = dh_idx;
 			}
 		}
 	}

 out:
 	return err;
 }



